-- Supabase tables used by the plugin (orders, products, rescues, split_config, payouts). orders.shopify_order_id is unique: one row per <order>::<product> line, and refund reversals use <order>::<product>::refund-<refund id>.
create table rescues (id uuid default gen_random_uuid() primary key, name text not null, slug text not null unique, email text, phone text, website text, address text, city text, state text, mission text, story text, logo_url text, hero_photo_url text, founding_year integer, animals_rescued integer default 0, status text default 'pending', ein text, stripe_account_id text, created_at timestamptz default now(), updated_at timestamptz default now(), video_url text, donate_url text, shopify_coffee_url text, about text, rescue_split_percent numeric default 55, w9_url text, points integer default 0);
create table products (id uuid default gen_random_uuid() primary key, name text not null, sku text not null unique, description text, roast_type text, size_oz integer, format text, price_cents integer not null, cost_cents integer not null, image_url text, active boolean default true, created_at timestamptz default now());
create table split_config (id uuid default gen_random_uuid() primary key, product_id uuid references products(id) on delete cascade, rescue_percent numeric not null, larry_percent numeric not null, updated_at timestamptz default now(), updated_by text);
create table orders (id uuid default gen_random_uuid() primary key, shopify_order_id text not null unique, rescue_id uuid references rescues(id), product_id uuid references products(id), quantity integer default 1, sale_amount_cents integer not null, rescue_split_cents integer not null, larry_split_cents integer not null, status text default 'pending', ordered_at timestamptz default now(), created_at timestamptz default now());
create table payouts (id uuid default gen_random_uuid() primary key, rescue_id uuid references rescues(id), amount_cents integer not null, stripe_transfer_id text, status text default 'pending', period_start date, period_end date, paid_at timestamptz, created_at timestamptz default now());
create table rescue_users (id uuid default gen_random_uuid() primary key, rescue_id uuid references rescues(id), email text not null unique, role text default 'rescue_admin', invited_at timestamptz, accepted_at timestamptz, created_at timestamptz default now());
alter table rescues enable row level security; alter table products enable row level security; alter table split_config enable row level security; alter table orders enable row level security; alter table payouts enable row level security; alter table rescue_users enable row level security;
revoke all on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
grant select (id, name, slug, city, state, mission, story, logo_url, hero_photo_url, founding_year, animals_rescued, status, website, video_url, donate_url, shopify_coffee_url, about) on rescues to anon, authenticated;
create policy "Public can read approved rescue profiles" on rescues for select to anon, authenticated using (status = any (array['approved','active']));
